/*-- Customize Options (Start) --

<Variable name="poppinsBold24" description="Poppins Bold 24" type="font" default="700 24px Poppins, sans-serif" hideEditor="true" value="700 24px Poppins, sans-serif"/>
<Variable name="poppinsBold18" description="Poppins Bold 18" type="font" default="700 18px Poppins, sans-serif" hideEditor="true" value="700 18px Poppins, sans-serif"/>
<Variable name="poppinsNormal16" description="Poppins Normal 16" type="font" default="16px Poppins, sans-serif" hideEditor="true" value="400 16px Poppins, sans-serif"/>
<Variable name="poppinsNormal13" description="Poppins Normal 13" type="font" default="13px Poppins, sans-serif" hideEditor="true" value="600 13px Poppins, sans-serif"/>

<Variable name="keycolor" description="Main Color" type="color" default="#0534ff"  value="#0534ff"/>

<Group description="Backgrounds Theme">
<Variable name="body.font" description="Font" type="font" default="$(poppinsNormal16)" value="400 15px Poppins, sans-serif"/>
<Variable name="body.link.color" description="Link color" type="color" default="#0001fc" value="#0001fc"/>
  <Variable name="body.background" description="Background" color="$(body.background.color)" type="background" default="$(color) none repeat scroll top left"  value="$(color) none repeat scroll top left"/>
  <Variable name="body.font.color" description="Text color" type="color" default="#242d3d"  value="#242d3d"/>
  <Variable name="body.background.color" description="Body background color" type="color" default="#fff" value="#ffffff"/>
  <Variable name="posts.background.color" description="Post background color" type="color" default="#fff" value="#ffffff"/>
  <Variable name="border.background.color" description="Background border" type="color" default="#e5e5e5" value="#e5e5e5"/>
</Group>

<Group description="Header Theme" selector="#header">
  <Variable name="logo.width" description="Logo width" type="length" min="1px" max="100px" default="68px"  value="68px"/>
  <Variable name="logo.height" description="Logo height" type="length" min="1px" max="100px" default="34px"  value="34px"/>
  <Variable name="header.color" description="Header background color" type="color" default="#111013" value="#111013"/>
  <Variable name="header.font.color" description="Header font color" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="header.font.hover" description="Header hover color" type="color" default="#c2e744" value="#c2e744"/>
  <Variable name="header.title.font" description="Font" type="font" default="$(poppinsNormal13)" value="600 14px Poppins, sans-serif"/>
</Group>

<Group description="Main Theme" selector="#main">
  <Variable name="title.font" description="Font title" type="font" default="$(poppinsBold16)" value="500 16px Poppins, sans-serif"/>
  <Variable name="price.font" description="Font price" type="font" default="$(poppinsBold24)" value="700 24px Poppins, sans-serif"/>
  <Variable name="meta.font" description="Font meta" type="color" default="#7d7d7d" value="#7d7d7d"/>
  <Variable name="meta.color" description="Font meta color" type="color" default="#555555" value="#555555"/>
  <Variable name="button.color" description="Button background color" type="color" default="#bbe913" value="#bbe913"/>
  <Variable name="button.font.color" description="Button font color" type="color" default="#101014" value="#101014"/>
  <Variable name="main.page.color" description="Main background color" type="color" default="#101014" value="#101014"/>
</Group>

<Group description="Footer Theme" selector="#footer">
  <Variable name="footer.color" description="Footer background color" type="color" default="#161519" value="#161519"/>
  <Variable name="footer.font.color" description="Footer font color" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="footer.font.hover" description="Footer hover color" type="color" default="#c2e744" value="#c2e744"/>
  <Variable name="footer.title.font" description="Font" type="font" default="$(poppinsBold16)" value="bold 16px Poppins, sans-serif"/>
</Group>

<Group description="Widths">
  <Variable name="header.height" description="Header height" type="length" min="1px" max="100px" default="70px"  value="70px"/>
  <Variable name="content.width" description="Content width" type="length" min="1px" max="1300px" default="1224px"  value="1224px"/>
</Group>

-- Customize Options (End) --*/

:root {
--main-color:$(keycolor);
--main-text:$(body.font.color);
--main-body-font:$(body.font);
--main-body-bg:$(body.background.color);
--head-color:$(header.color);
--head-text:$(header.font.color);
--head-font:$(header.title.font);
--logo-width:$(logo.width);
--logo-height:$(logo.height);
--head-hover:$(header.font.hover);
--head-height:$(header.height);
--main-title-post:$(title.font);
--main-price:$(price.font);
--main-meta:$(meta.font);
--main-meta-color:$(meta.color);
--main-post-bg:$(posts.background.color);
--main-border:$(border.background.color);
--main-width:$(content.width);
--main-button:$(button.color);
--main-button-font:$(button.font.color);
--main-page-bg:$(main.page.color);
--main-footer-bg:$(footer.color);
--main-footer-font:$(footer.title.font);
--main-footer-hover:$(footer.font.hover);
--main-footer-color:$(footer.font.color);
--main-menu-shadow: rgba(0, 0, 0, 0.2) 0px 14px 12px -8px;
}

body[data-theme="dark"] {
--main-body-bg:#1d1d1d;
--main-post-bg:#1d1d1d;
--main-text:#ffffff;
--main-meta:#cccccc;
--head-color:#111013;
--main-link-header:var(--main-text);
--main-line-hr:#313131;
--main-border:#313131;
--main-meta-color:#eeeeee;
--main-menu-shadow:0 20px 32px -8px color-mix(in srgb, black 30%, transparent), 0 0 1px color-mix(in srgb, black 15%, transparent);
--main-footer-bg:#161519;
}

